#include <sys/mman.h>
#include <sys/stat.h>
#include <pthread.h>
#include <errno.h>

#define NTHREAD 6
#define TSIZE 1024
#define LO 0x0101010101010101ULL
#define HI 0x8080808080808080ULL
#define SEMIS 0x3b3b3b3b3b3b3b3bULL

typedef struct {
    const char *name;
    int64_t sum;
    uint32_t count;
    int16_t min, max;
    uint16_t len;
} Entry;

typedef struct {
    const char *data;
    const char *start;
    const char *end;
    Entry tab[TSIZE];
} Worker;

static inline uint64_t load64(const void *p) {
    uint64_t x; __builtin_memcpy(&x, p, 8); return x;
}
static inline uint64_t semimask(uint64_t w) {
    uint64_t x = w ^ SEMIS;
    return (x - LO) & ~x & HI;
}
static inline uint64_t mix(uint64_t x) {
    x ^= x >> 30; x *= 0xbf58476d1ce4e5b9ULL;
    x ^= x >> 27; x *= 0x94d049bb133111ebULL;
    return x ^ (x >> 31);
}

static void *work(void *arg) {
    Worker *a = (Worker *)arg;
    const char *p = a->start, *end = a->end;
    Entry *tab = a->tab;
    while (p < end) {
        const char *name = p;
        uint64_t h = 0x9e3779b97f4a7c15ULL;
        uint64_t w, m;
        for (;;) {
            w = load64(p);
            m = semimask(w);
            if (m) break;
            h = (h ^ mix(w)) * 0x9e3779b185ebca87ULL;
            p += 8;
        }
        unsigned n = (unsigned)(__builtin_ctzll(m) >> 3);
        uint64_t tail = n ? (w & ((1ULL << (n * 8)) - 1)) : 0;
        h = mix(h ^ tail ^ ((uint64_t)(p + n - name) * 0xd6e8feb86659fd93ULL));
        p += n + 1;
        unsigned len = (unsigned)(p - name - 1);

        int neg = (*p == '-');
        p += neg;
        int t;
        if (p[1] == '.') {
            t = (p[0] - '0') * 10 + (p[2] - '0');
            p += 4;
        } else {
            t = (p[0] - '0') * 100 + (p[1] - '0') * 10 + (p[3] - '0');
            p += 5;
        }
        if (neg) t = -t;

        Entry *e = &tab[h & (TSIZE - 1)];
        while (e->name && (e->len != len || memcmp(e->name, name, len))) {
            e = &tab[((unsigned)(e - tab) + 1) & (TSIZE - 1)];
        }
        if (!e->name) {
            e->name = name; e->len = len; e->sum = t; e->count = 1;
            e->min = e->max = (int16_t)t;
        } else {
            e->sum += t; e->count++;
            if (t < e->min) e->min = (int16_t)t;
            if (t > e->max) e->max = (int16_t)t;
        }
    }
    return NULL;
}

static int cmpentry(const void *aa, const void *bb) {
    const Entry *a = *(Entry * const *)aa, *b = *(Entry * const *)bb;
    unsigned n = a->len < b->len ? a->len : b->len;
    int c = memcmp(a->name, b->name, n);
    return c ? c : (int)a->len - (int)b->len;
}
